B.apA=new A.b5("p01","\u0627\u0644\u063a\u0627\u0641","Ghaf tree","Prosopis cineraria",B.cR,B.aB,B.aE,B.aU,10,!1,"\u0634\u062c\u0631\u0629 \u0645\u062d\u0644\u064a\u0629 \u062f\u0627\u0626\u0645\u0629 \u0627\u0644\u062e\u0636\u0631\u0629 \u062a\u062a\u062d\u0645\u0644 \u0627\u0644\u062d\u0631 \u0648\u0627\u0644\u062c\u0641\u0627\u0641\u060c \u0645\u0646\u0627\u0633\u0628\u0629 \u0644\u0644\u0638\u0644 \u0641\u064a \u0627\u0644\u062d\u062f\u0627\u0626\u0642 \u0648\u0627\u0644\u0627\u0633\u062a\u0631\u0627\u062d\u0627\u062a.","Native evergreen that tolerates heat and drought; good shade tree for gardens.",u.B,!1,null,null,null,null)
B.apI=new A.b5("p02","\u0627\u0644\u0633\u0645\u0631","Umbrella thorn acacia","Vachellia tortilis",B.cR,B.aB,B.aE,B.aU,14,!1,"\u0634\u062c\u0631\u0629 \u0635\u062d\u0631\u0627\u0648\u064a\u0629 \u0645\u0638\u0644\u064a\u0629 \u0627\u0644\u0634\u0643\u0644\u060c \u062a\u062d\u062a\u0627\u062c \u0645\u0627\u0621\u064b \u0642\u0644\u064a\u0644\u0627\u064b \u062c\u062f\u0627\u064b \u0628\u0639\u062f \u0623\u0646 \u062a\u062b\u0628\u062a.","Umbrella-shaped desert tree; needs very little water once established.","RCRC \u2014 Manual of Riyadh Plants",!0,null,null,null,"Part 2: Plant portraits, p. 35 (Acacia tortilis ssp. spirocarpa)")
B.apn=new A.b5("p03","\u0627\u0644\u0633\u062f\u0631","Christ's thorn jujube","Ziziphus spina-christi",B.cR,B.aB,B.aE,B.aU,10,!1,"\u0634\u062c\u0631\u0629 \u0645\u062d\u0644\u064a\u0629 \u0645\u0639\u0645\u0631\u0629 \u062a\u0639\u0637\u064a \u062b\u0645\u0631 \u0627\u0644\u0646\u0628\u0642 \u0648\u0638\u0644\u0627\u064b \u0643\u062b\u064a\u0641\u0627\u064b \u0648\u062a\u062a\u062d\u0645\u0644 \u0645\u0644\u0648\u062d\u0629 \u0627\u0644\u062a\u0631\u0628\u0629.","Long-lived native tree with edible fruit and dense shade; tolerates salty soil.","RCRC \u2014 Manual of Riyadh Plants",!0,null,null,null,"Part 2: Plant portraits, p. 322")
B.apB=new A.b5("p04","\u0646\u062e\u0644\u0629 \u0627\u0644\u062a\u0645\u0631","Date palm","Phoenix dactylifera",B.hS,B.aB,B.aE,B.dY,7,!1,"\u0627\u0644\u0646\u062e\u0644\u0629 \u0627\u0644\u0645\u0639\u0631\u0648\u0641\u0629\u060c \u062a\u062d\u062a\u0627\u062c \u0634\u0645\u0633\u0627\u064b \u0643\u0627\u0645\u0644\u0629 \u0648\u0631\u064a \u0645\u0646\u062a\u0638\u0645 \u0641\u064a \u0627\u0644\u0635\u064a\u0641.","The classic date palm; full sun and regular summer watering.","RCRC \u2014 Manual of Riyadh Plants",!0,null,"Date palm",null,"Part 2: Plant portraits, p. 230")
B.apG=new A.b5("p05","\u0627\u0644\u0623\u062b\u0644","Athel tamarisk","Tamarix aphylla",B.cR,B.aB,B.aE,B.aU,10,!1,"\u0634\u062c\u0631\u0629 \u0633\u0631\u064a\u0639\u0629 \u0627\u0644\u0646\u0645\u0648 \u062a\u0633\u062a\u062e\u062f\u0645 \u0643\u0645\u0635\u062f\u0627\u062a \u0631\u064a\u0627\u062d\u060c \u062a\u062a\u062d\u0645\u0644 \u0627\u0644\u0645\u0644\u0648\u062d\u0629.","Fast-growing windbreak tree that tolerates salinity.","RCRC \u2014 Manual of Riyadh Plants",!0,null,null,null,"Part 2: Plant portraits, p. 292")
B.apM=new A.b5("p06","\u0627\u0644\u0637\u0644\u062d","Gerrard's acacia","Vachellia gerrardii",B.cR,B.aB,B.aE,B.aU,14,!1,"\u0634\u062c\u0631\u0629 \u0628\u0631\u064a\u0629 \u0645\u062d\u0644\u064a\u0629 \u0645\u0646 \u0634\u062c\u0631 \u0627\u0644\u0631\u0648\u0636\u0627\u062a\u060c \u0642\u0644\u064a\u0644\u0629 \u0627\u0644\u0627\u062d\u062a\u064a\u0627\u062c \u0644\u0644\u0645\u0627\u0621.","Native wild acacia of the Najd meadows; low water needs.","RCRC \u2014 Manual of Riyadh Plants",!0,null,null,null,"Part 2: Plant portraits, p. 25 (Acacia gerrardii)")
B.apO=new A.b5("p07","\u0627\u0644\u0628\u0627\u0646","Wild moringa","Moringa peregrina",B.cR,B.aB,B.aE,B.aU,10,!1,"\u0634\u062c\u0631\u0629 \u0645\u062d\u0644\u064a\u0629 \u0631\u0634\u064a\u0642\u0629 \u0628\u0623\u0648\u0631\u0627\u0642 \u062f\u0642\u064a\u0642\u0629 \u0648\u0623\u0632\u0647\u0627\u0631 \u0639\u0637\u0631\u064a\u0629.","Slender native tree with fine leaves and fragrant flowers.",u.B,!1,null,null,null,null)
B.apo=new A.b5("p08","\u0627\u0644\u0628\u0627\u0631\u0643\u0646\u0633\u0648\u0646\u064a\u0627","Jerusalem thorn","Parkinsonia aculeata",B.cR,B.aB,B.aE,B.aU,10,!1,"\u0634\u062c\u0631\u0629 \u0635\u063a\u064a\u0631\u0629 \u0628\u0623\u0632\u0647\u0627\u0631 \u0635\u0641\u0631\u0627\u0621\u060c \u062a\u062a\u062d\u0645\u0644 \u0627\u0644\u062d\u0631 \u0648\u0627\u0644\u062c\u0641\u0627\u0641.","Small tree with yellow flowers; heat and drought tolerant.","RCRC \u2014 Manual of Riyadh Plants",!0,null,null,null,"Part 2: Plant portraits, p. 220")
B.apV=new A.b5("p09","\u0627\u0644\u0644\u0628\u062e","Siris tree","Albizia lebbeck",B.cR,B.aB,B.aE,B.dY,7,!1,"\u0634\u062c\u0631\u0629 \u0638\u0644 \u0643\u0628\u064a\u0631\u0629 \u0633\u0631\u064a\u0639\u0629 \u0627\u0644\u0646\u0645\u0648\u060c \u062a\u062d\u062a\u0627\u062c \u0645\u0633\u0627\u062d\u0629 \u0648\u0627\u0633\u0639\u0629.","Large fast-growing shade tree; needs plenty of space.","RCRC \u2014 Manual of Riyadh Plants",!0,null,null,null,"Part 2: Plant portraits, p. 44")
B.apJ=new A.b5("p10","\u0627\u0644\u0628\u0648\u0646\u0633\u064a\u0627\u0646\u0627","Royal poinciana","Delonix regia",B.cR,B.aB,B.aE,B.dY,5,!1,"\u0634\u062c\u0631\u0629 \u0632\u064a\u0646\u0629 \u0628\u0623\u0632\u0647\u0627\u0631 \u062d\u0645\u0631\u0627\u0621 \u0632\u0627\u0647\u064a\u0629 \u0641\u064a \u0627\u0644\u0635\u064a\u0641.","Ornamental tree with bright red summer flowers.","RCRC \u2014 Manual of Riyadh Plants",!0,null,null,null,"Part 2: Plant portraits, p. 128")
B.apm=new A.b5("p11","\u0646\u062e\u064a\u0644 \u0627\u0644\u0648\u0627\u0634\u0646\u0637\u0648\u0646\u064a\u0627","California fan palm","Washingtonia filifera",B.hS,B.aB,B.aE,B.dY,7,!1,"\u0646\u062e\u0644\u0629 \u0645\u0631\u0648\u062d\u064a\u0629 \u0627\u0644\u0623\u0648\u0631\u0627\u0642 \u0644\u0644\u0634\u0648\u0627\u0631\u0639 \u0648\u0627\u0644\u062d\u062f\u0627\u0626\u0642 \u0627\u0644\u0643\u0628\u064a\u0631\u0629.","Fan-leaf palm for streets and large gardens.","RCRC \u2014 Manual of Riyadh Plants",!0,null,null,null,"Part 2: Plant portraits, p. 311")
B.apK=new A.b5("p12","\u0627\u0644\u0634\u062b","Hopbush","Dodonaea viscosa",B.c7,B.aB,B.aE,B.aU,7,!1,"\u0634\u062c\u064a\u0631\u0629 \u0645\u062d\u0644\u064a\u0629 \u062a\u0635\u0644\u062d \u0643\u0633\u064a\u0627\u062c \u0623\u062e\u0636\u0631\u060c \u062a\u062a\u062d\u0645\u0644 \u0627\u0644\u062d\u0631.","Native shrub that makes a good hedge; heat tolerant.","RCRC \u2014 Manual of Riyadh Plants",!0,null,null,null,"Part 2: Plant portraits, p. 129")
B.apv=new A.b5("p13","\u0627\u0644\u0644\u064a\u0648\u0643\u0648\u0641\u064a\u0644\u0645","Texas sage","Leucophyllum frutescens",B.c7,B.aB,B.aE,B.aU,7,!1,"\u0634\u062c\u064a\u0631\u0629 \u0641\u0636\u064a\u0629 \u0627\u0644\u0623\u0648\u0631\u0627\u0642 \u0628\u0623\u0632\u0647\u0627\u0631 \u0628\u0646\u0641\u0633\u062c\u064a\u0629\u060c \u0642\u0644\u064a\u0644\u0629 \u0627\u0644\u0631\u064a.","Silver-leaved shrub with purple flowers; little watering.","RCRC \u2014 Manual of Riyadh Plants",!0,null,null,null,"Part 2: Plant portraits, p. 191")
B.aps=new A.b5("p14","\u0627\u0644\u062a\u064a\u0643\u0648\u0645\u0627","Yellow bells","Tecoma stans",B.c7,B.aB,B.aE,B.dY,4,!1,"\u0634\u062c\u064a\u0631\u0629 \u0645\u0632\u0647\u0631\u0629 \u0628\u0623\u0632\u0647\u0627\u0631 \u0635\u0641\u0631\u0627\u0621 \u062c\u0631\u0633\u064a\u0629 \u0645\u0639\u0638\u0645 \u0627\u0644\u0633\u0646\u0629.","Flowering shrub with yellow bell flowers most of the year.","RCRC \u2014 Manual of Riyadh Plants",!0,null,null,null,"Part 2: Plant portraits, p. 295")
B.apR=new A.b5("p15","\u0627\u0644\u062f\u0641\u0644\u0629","Oleander","Nerium oleander",B.c7,B.aB,B.aE,B.aU,7,!0,"\u0634\u062c\u064a\u0631\u0629 \u0645\u0632\u0647\u0631\u0629 \u0642\u0648\u064a\u0629 \u0627\u0644\u062a\u062d\u0645\u0644\u060c \u0644\u0643\u0646\u0647\u0627 \u0633\u0627\u0645\u0629 \u0644\u062c\u0645\u064a\u0639 \u0623\u062c\u0632\u0627\u0626\u0647\u0627.","Tough flowering shrub; every part of the plant is poisonous.","RCRC \u2014 Manual of Riyadh Plants",!0,null,"Nerium",null,"Part 2: Plant portraits, p. 211")
